UPDATE risk_knowledge_solutions SET retest_acceptance_json='["ARL-KB-103: Original failure verification — replay the same canonical input and material preconditions documented in the confirmed finding against the exact remediated version. Preserve observed evidence that the original undesired effect no longer occurs; if the case cannot be validly repeated, closure remains inconclusive.","ARL-KB-103: Authorised-path regression — Restore representative backed-up AI state in isolation and verify expected records, relationships and integrity checks succeed. Record expected and observed outcomes with source or execution provenance.","ARL-KB-103: Relevant abuse and bypass regression — Remove or corrupt a synthetic backup component or manifest and verify restoration does not silently produce an incomplete or falsely trusted state. Record the real control-boundary outcome rather than assuming universal denial before side effects.","ARL-KB-103: Accountable closure — link the original failure, exact retest evidence digests, system SHA, tested configuration, written authorisation where needed, known limitations, reviewer identity and timestamp. Any missing lineage or unresolved regression keeps closure blocked."]', content_digest='17227427ea3092e01e575ea57daa1dce8f03b5f425d849010a0e1345d10b737f' WHERE entry_id='ARL-KB-103';
